@AI 
{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": "/results.csv"
  },
  "mark": "point",
  "transform": [
    {
      "aggregate": [
        {
          "op": "mean",
          "field": "home_score",
          "as": "mean_home_score"
        },
        {
          "op": "mean",
          "field": "away_score",
          "as": "mean_away_score"
        }
      ]
    },
    {
      "fold": ["mean_home_score", "mean_away_score"],
      "as": ["score_type", "score_value"]
    }
  ],
  "encoding": {
    "x": {"field": "score_type", "type": "nominal"}, 
    "y": {"field": "score_value", "type": "quantitative"}
  }
}


